# Move a claim to a status (open, settle or void). A change its current status does not allow is
# refused before anything is written.
validate:
  class: net.officefloor.hq.app.sheet.ValidateSheetId
  next: status
status:
  class: net.officefloor.hq.app.claim.ValidateClaimStatus
  next: load
load:
  class: net.officefloor.hq.app.claim.LoadClaim
  govern: [ transaction ]
  next: closed
closed:
  class: net.officefloor.hq.app.claim.RefuseClosedClaim
  govern: [ transaction ]
  next: rollup-before
rollup-before:
  class: net.officefloor.hq.app.rollup.SnapshotRollup
  govern: [ transaction ]
  next: apply
apply:
  class: net.officefloor.hq.app.claim.ApplyClaimStatus
  govern: [ transaction ]
  next: audit
audit:
  class: net.officefloor.hq.app.claim.RecordClaimStatus
  govern: [ transaction ]
  next: rollup
rollup:
  class: net.officefloor.hq.app.rollup.RecordRollup
  govern: [ transaction ]
  next: respond
respond:
  class: net.officefloor.hq.app.claim.RespondWithClaim
  govern: [ transaction ]
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.access.LateCharge;
import net.officefloor.hq.app.access.Role;
import net.officefloor.hq.app.access.RoleRepository;
import net.officefloor.hq.app.access.SettingRepository;
import net.officefloor.hq.app.period.Period;
import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.rate.RateRepository;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Moves the claim to the asked status, refusing a change its current status does not allow,
 * refusing to let the user who opened it settle it, and refusing a clerk a settle whose due is above the sheet's
 * clerk limit (a due of n/a is within any limit; a steward settles anything). Opening records who opened it; a voided claim keeps its number. Settling
 * fixes the claim's due at the rate in force on the claim's date of its person's grade on that date (at least the sheet's floor) — or, while a statement binds it, at
 * the figure it was bound to — with its late charge as of the sheet's today frozen in on top; without a figure its due stays live.
 */
public class ApplyClaimStatus {
    public void apply(@Val ClaimStatus status, @Val Claim claim, ClaimRepository repository,
            PersonRepository people, RateRepository rates, RoleRepository roles, SettingRepository settings, SheetRepository sheets,
            PeriodRepository periods, @Val ChangedBy by, Out<ClaimNumber> audited) throws BadRequestException {
        ClaimStatus from = claim.getStatus();
        if (!from.canBecome(status)) {
            throw new BadRequestException("A " + from + " claim cannot become " + status);
        }
        if (status == ClaimStatus.SETTLED && by.name().equals(claim.getOpenedBy())) {
            throw new BadRequestException("The user who opened a claim cannot settle it");
        }
        LateCharge late = settings.lateCharge(claim.getSheetId(), sheets.today(claim.getSheetId()));
        BigDecimal due = status == ClaimStatus.SETTLED ? late.due(claim, dueNow(claim, people, rates, settings, late)) : null;
        if (status == ClaimStatus.SETTLED && due != null
                && !Role.STEWARD.equals(roles.roleOf(claim.getSheetId(), by.name()))) {
            BigDecimal limit = settings.clerkLimit(claim.getSheetId());
            if (limit != null && due.compareTo(limit) > 0) {
                throw new BadRequestException("A clerk can settle a claim only when its due is at or below the clerk limit ("
                        + limit.toPlainString() + ")");
            }
        }
        claim.setStatus(status);
        if (status == ClaimStatus.OPEN) {
            claim.setOpenedBy(by.name());
        }
        if (status == ClaimStatus.SETTLED) {
            claim.setSettledDue(due);
        }
        if (!repository.updateStatus(claim, from)) {
            throw new BadRequestException("The claim was changed by someone else; reload the sheet");
        }
        if (status == ClaimStatus.OPEN) {
            // Numbered only once the claim is surely moving, so a refused open uses up no number.
            claim.setNumber(number(claim, repository, settings, sheets, periods));
            repository.updateStatus(claim, status);
        }
        audited.set(new ClaimNumber(claim.getNumber()));
    }

    /**
     * The number an opened claim takes: while the sheet numbers by period and its today is on or after that setting's
     * date, the next within the claim's period (by its date) as {@code <period name>-<n>}, or {@code X-<n>} in no period;
     * otherwise the sheet's next.
     */
    private static String number(Claim claim, ClaimRepository repository, SettingRepository settings,
            SheetRepository sheets, PeriodRepository periods) {
        String sheetId = claim.getSheetId();
        java.time.LocalDate from = settings.periodNumberingFrom(sheetId);
        if (from == null || sheets.today(sheetId).isBefore(from)) {
            return String.valueOf(repository.nextNumber(sheetId));
        }
        Period period = periods.on(sheetId, claim.getDate());
        return period == null ? "X-" + repository.nextNumber(sheetId, "X")
                : period.name() + "-" + repository.nextNumber(sheetId, String.valueOf(period.id()));
    }

    /** The figure a statement bound the claim to, else the claim's amount times its person's grade's rate on the claim's date, rounded as the claim rounds by the sheet's policy date and at least the sheet's floor (a correction has none); null when there is no rate. */
    private static BigDecimal dueNow(Claim claim, PersonRepository people, RateRepository rates,
            SettingRepository settings, LateCharge late) {
        if (claim.isStated()) {
            return claim.getStatedDue();
        }
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        BigDecimal rate = person == null ? null : rates.find(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
        return claim.figureAt(rate, settings.floor(claim.getSheetId()), late.rounding(claim));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.BadRequestException;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** The status asked for: OPEN, SETTLED or VOID. Publishes it with the user making the change. */
public class ValidateClaimStatus {
    public void validate(@RequestBody ClaimStatusRequest request, Out<ClaimStatus> status,
            Out<ChangedBy> changedBy) throws BadRequestException {
        ChangedBy by = ChangedBy.of(request == null ? null : request.by());
        String asked = request == null || request.status() == null ? "" : request.status().trim();
        ClaimStatus parsed;
        try {
            parsed = ClaimStatus.valueOf(asked);
        } catch (IllegalArgumentException e) {
            throw new BadRequestException("A status is OPEN, SETTLED or VOID");
        }
        if (parsed == ClaimStatus.DRAFT) {
            throw new BadRequestException("A status is OPEN, SETTLED or VOID");
        }
        status.set(parsed);
        changedBy.set(by);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.session.ChangedBy;
import net.officefloor.plugin.variable.Val;

public class RecordClaimStatus {
    public void record(@Val Claim claim, @Val ClaimNumber number, @Val ChangedBy by, PersonRepository people, Audit audit) {
        String event = switch (claim.getStatus()) {
            case OPEN -> "CLAIM_OPENED";
            case SETTLED -> "CLAIM_SETTLED";
            case VOID -> "CLAIM_VOIDED";
            case DRAFT -> throw new IllegalStateException("A claim never returns to DRAFT");
        };
        Person person = people.find(claim.getSheetId(), claim.getPersonId());
        String line = ClaimAudit.line(event, claim, by, person == null ? "" : person.getName(), number.value());
        if (claim.getStatus() == ClaimStatus.SETTLED) {
            line += " due=" + (claim.getSettledDue() == null ? "n/a" : claim.getSettledDue().toPlainString());
        }
        audit.record(line);
    }
}
package net.officefloor.hq.app.claim;

/** A claim's status: DRAFT → OPEN → SETTLED, and a DRAFT or OPEN claim may become VOID. */
public enum ClaimStatus {
    DRAFT, OPEN, SETTLED, VOID;

    /** Whether a claim in this status may move to {@code next}. */
    public boolean canBecome(ClaimStatus next) {
        return switch (next) {
            case OPEN -> this == DRAFT;
            case SETTLED -> this == OPEN;
            case VOID -> this == DRAFT || this == OPEN;
            case DRAFT -> false;
        };
    }

    /** Whether a claim in this status counts toward claimed, due and every total. */
    public boolean counts() {
        return this == OPEN || this == SETTLED;
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.session.ChangedBy;

/**
 * A claim's audit record: the event, sheet, user, then person, amount (two decimals) and date, and
 * the claim's number when it has one.
 */
final class ClaimAudit {

    private ClaimAudit() {
    }

    static String line(String event, Claim claim, ChangedBy by, String personName) {
        return line(event, claim, by, personName, claim.getNumber());
    }

    static String line(String event, Claim claim, ChangedBy by, String personName, String number) {
        return event + " sheet=" + claim.getSheetId() + " by=" + by.name() + " person=" + personName + " amount="
                + claim.getAmount().setScale(2).toPlainString() + " date=" + claim.getDate()
                + (number == null ? "" : " number=" + number);
    }
}
package net.officefloor.hq.app.claim;

import java.math.BigDecimal;
import java.time.LocalDate;

/** A claim of a person on a sheet. Mutable so an Apply step can change it in place. */
public class Claim {

    private final long id;
    private final String sheetId;
    private final long personId;
    private BigDecimal amount;
    private LocalDate date;
    private String note;
    private ClaimStatus status;
    private String number;
    private BigDecimal settledDue;
    private String openedBy;
    private boolean stated;
    private BigDecimal statedDue;
    private String corrects;
    private LocalDate roundOn;

    public Claim(long id, String sheetId, long personId, BigDecimal amount, LocalDate date, String note,
            ClaimStatus status, String number, BigDecimal settledDue, String openedBy,
            boolean stated, BigDecimal statedDue, String corrects) {
        this.id = id;
        this.sheetId = sheetId;
        this.personId = personId;
        this.amount = amount;
        this.date = date;
        this.note = note;
        this.status = status;
        this.number = number;
        this.settledDue = settledDue;
        this.openedBy = openedBy;
        this.stated = stated;
        this.statedDue = statedDue;
        this.corrects = corrects;
        this.roundOn = date;
    }

    /** The date the claim's live figures round by: its own, or for a correction the date of the claim it corrects. */
    public LocalDate getRoundOn() {
        return roundOn;
    }

    public void setRoundOn(LocalDate roundOn) {
        this.roundOn = roundOn;
    }

    public long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public long getPersonId() {
        return personId;
    }

    public BigDecimal getAmount() {
        return amount;
    }

    public void setAmount(BigDecimal amount) {
        this.amount = amount;
    }

    public LocalDate getDate() {
        return date;
    }

    public void setDate(LocalDate date) {
        if (corrects == null) {
            this.roundOn = date;
        }
